from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/final_capstone/portfolio_lab.json").read_text(
        encoding="utf-8"
    )
)
for project, card in lab["cards"].items():
    print(project, card["protocol"])
assert lab["report"]["reserved_outcomes_newly_scored"] == 0

from pathlib import Path
